<?php
require __DIR__.'/config.php';$user=require_login();$method=$_SERVER['REQUEST_METHOD']??'';
function valid_delivery_date(string $date): bool { if($date==='')return true;$parsed=DateTime::createFromFormat('!Y-m-d H:i',$date);$errors=DateTime::getLastErrors();return $parsed!==false&&($errors===false||($errors['warning_count']===0&&$errors['error_count']===0))&&$parsed->format('Y-m-d H:i')===$date; }
if($method==='GET'){
 if($user['rol']==='ADMIN')$rows=db()->query('SELECT e.*,p.estado AS estado_pedido,u.nombre AS cliente FROM entregas e JOIN pedidos p ON p.id=e.pedido_id JOIN clientes c ON c.id=p.cliente_id JOIN usuarios u ON u.id=c.usuario_id ORDER BY e.id DESC')->fetchAll();
 else{$q=db()->prepare('SELECT e.*,p.estado AS estado_pedido FROM entregas e JOIN pedidos p ON p.id=e.pedido_id JOIN clientes c ON c.id=p.cliente_id WHERE c.usuario_id=? ORDER BY e.id DESC');$q->execute([$user['id']]);$rows=$q->fetchAll();}
 json_response(true,$rows,'Entregas consultadas.');
}
require_admin();require_csrf();$data=body();
 if($method==='POST'){$order=filter_var($data['pedido_id']??null,FILTER_VALIDATE_INT);$address=trim((string)($data['direccion']??''));$date=trim((string)($data['fecha_programada']??''));if(!$order||$address===''||mb_strlen($address)>255||!valid_delivery_date($date))json_response(false,null,'Indica un pedido, dirección y fecha válidos.',400);$q=db()->prepare('SELECT id FROM pedidos WHERE id=?');$q->execute([$order]);if(!$q->fetch())json_response(false,null,'Pedido no encontrado.',404);try{$q=db()->prepare('INSERT INTO entregas(pedido_id,direccion,fecha_programada) VALUES(?,?,?)');$q->execute([$order,$address,$date?:null]);json_response(true,['id'=>(int)db()->lastInsertId()],'Entrega programada.',201);}catch(PDOException $e){if($e->getCode()==='23000')json_response(false,null,'Este pedido ya tiene una entrega registrada.',409);throw $e;}}
 if($method==='PUT'){$id=filter_var($data['id']??null,FILTER_VALIDATE_INT);$state=$data['estado']??'';$address=trim((string)($data['direccion']??''));$date=trim((string)($data['fecha_programada']??''));if(!$id||!in_array($state,['PENDIENTE','EN_RUTA','ENTREGADA','NOVEDAD'],true)||$address===''||mb_strlen($address)>255||!valid_delivery_date($date))json_response(false,null,'Revisa la entrega, dirección y fecha.',400);$q=db()->prepare('UPDATE entregas SET estado=?,direccion=?,fecha_programada=? WHERE id=?');$q->execute([$state,$address,$date?:null,$id]);if(!$q->rowCount())json_response(false,null,'Entrega no encontrada o sin cambios.',404);json_response(true,null,'Entrega actualizada.');}
require_method(['GET','POST','PUT']);
